    VALUES (NULL, $q$Roll Forming - Roll Tooling$q$, 'process', 'single', false, true, true, $q$One set of the mill's rolls: the tooling multiplier (toolingMultiplier_Standard, or toolingMultiplier_Panel for a panel profile; the Cost Guide's rollFormToolingMultiplier when set) x the strip width x the roll stations, with profit and SG&A. The data gives the multipliers (design, material and machining) and no formula: this rule is the engine's own, agreed with the user 2026-11-22.$q$)
    RETURNING id INTO v_id;
  ELSE
