    (v_id, $q$Tool Subtotal$q$, $q$Tool Subtotal (USD)$q$, $q$calculated$q$, $q$USD$q$, NULL, NULL, NULL, $q${Tooling Multiplier} * {Strip Width} * {Roll Stations}$q$, 6, false),
    (v_id, $q$Tool Cost$q$, $q$Tool Cost (USD)$q$, $q$calculated$q$, $q$USD$q$, NULL, NULL, NULL, $q${Tool Subtotal} * (1 + {Profit} + {SG and A})$q$, 7, false);
