$calc$;

-- Roll Forming - Press Die
DO $calc$
DECLARE v_id UUID;
BEGIN
  SELECT id INTO v_id FROM public.calculators WHERE name = $q$Roll Forming - Press Die$q$ AND user_id IS NULL AND retired_at IS NULL;
  IF v_id IS NULL THEN
    INSERT INTO public.calculators (user_id, name, calc_category, calculator_type, is_template, is_public, is_global, description)
    VALUES (NULL, $q$Roll Forming - Press Die$q$, 'process', 'single', false, true, true, $q$One die of a press on the line (the punch press's progressive die, or the cut-off die), by a compact die model: its design (punchPressDesignPreparationHrs + punchPressDieBaseDesignHrs) and assembly (punchPressToolingAssemblyHrs) at the tool shop's rates; its upper and lower die shoes (dieShoeSizes for the die's plan) in tool steel and their machining (cncMillingRates profiling); the standard components of each punched feature (componentStandardCosts: pierce punch, die button, punch retainer, stripper pin); the cut-off's blade or scissor inserts (toolingComponentAttributes); the die's carrying, freight, gage and welding costs; heat treatment when cutOffToolingHeatTreat / punchToolingHeatTreat says so; tuning on the cut-off die (percentTuning); with profit and SG&A. Shop rates and tool steel: the Digital Factory USA Default tool shop. The model is the engine's own, agreed with the user 2026-11-22.$q$)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.calculators SET calc_category = 'process', description = $q$One die of a press on the line (the punch press's progressive die, or the cut-off die), by a compact die model: its design (punchPressDesignPreparationHrs + punchPressDieBaseDesignHrs) and assembly (punchPressToolingAssemblyHrs) at the tool shop's rates; its upper and lower die shoes (dieShoeSizes for the die's plan) in tool steel and their machining (cncMillingRates profiling); the standard components of each punched feature (componentStandardCosts: pierce punch, die button, punch retainer, stripper pin); the cut-off's blade or scissor inserts (toolingComponentAttributes); the die's carrying, freight, gage and welding costs; heat treatment when cutOffToolingHeatTreat / punchToolingHeatTreat says so; tuning on the cut-off die (percentTuning); with profit and SG&A. Shop rates and tool steel: the Digital Factory USA Default tool shop. The model is the engine's own, agreed with the user 2026-11-22.$q$, updated_at = now() WHERE id = v_id;
  END IF;

