    (v_id, $q$Die Cost$q$, $q$Die Cost (USD)$q$, $q$calculated$q$, $q$USD$q$, NULL, NULL, NULL, $q${Die Subtotal} * (1 + {Tuning}) * (1 + {Profit} + {SG and A})$q$, 30, false);
