$calc$;

-- Post-check: every calculator exists once, with all its fields, linked to every operation it computes.
DO $post$
DECLARE bad TEXT;
BEGIN
  SELECT string_agg(e.name, ', ') INTO bad
  FROM (VALUES
    ($q$Roll Forming - Coil Material Stock$q$, 8, 1),
    ($q$Roll Forming - Uncoiler$q$, 8, 1),
    ($q$Roll Forming - Coil Flattener$q$, 8, 1),
    ($q$Roll Forming - Punch Press$q$, 8, 1),
    ($q$Roll Forming - Roll Forming Mill$q$, 8, 1),
    ($q$Roll Forming - Integrated Welding$q$, 8, 4),
    ($q$Roll Forming - Cut-Off Press$q$, 11, 1),
    ($q$Roll Forming - Stations$q$, 6, 0),
    ($q$Roll Forming - Line Speed$q$, 14, 0),
    ($q$Roll Forming - Coil Change$q$, 16, 0),
    ($q$Roll Forming - Die Sharpening$q$, 6, 0),
    ($q$Roll Forming - Strip$q$, 8, 0),
    ($q$Roll Forming - Material$q$, 3, 0),
    ($q$Roll Forming - Press Force$q$, 4, 0),
    ($q$Roll Forming - Roll Tooling$q$, 7, 0),
    ($q$Roll Forming - Press Die$q$, 30, 0)
  ) AS e(name, field_count, mapping_count)
  LEFT JOIN public.calculators c ON c.name = e.name AND c.user_id IS NULL AND c.retired_at IS NULL
  WHERE c.id IS NULL
     OR (SELECT count(*) FROM public.calculator_fields f WHERE f.calculator_id = c.id) <> e.field_count
     OR (SELECT count(*) FROM public.process_calculator_mappings m WHERE m.calculator_id = c.id AND m.process_group = $q$Sheet Metal Roll Forming$q$ AND (m.is_active OR m.machine_class IS NULL)) <> e.mapping_count;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'migration 1113: calculators incomplete: %', bad;
  END IF;
END
$post$;

COMMIT;
